#include "Diagnostics.h"
#include "DemucsSeparator.h"
#include "SeparationEngine.h"
#include "StemCache.h"

#include <juce_audio_processors/juce_audio_processors.h>

#include "SplittrBuildInfo.h" // generated by cmake/BuildInfo.cmake at build time

#if JUCE_MAC
 #include <sys/sysctl.h>
#endif

namespace splittr
{

namespace
{
    juce::String line (const juce::String& label, const juce::String& value)
    {
        return label.paddedRight (' ', 14) + value + "\n";
    }

    juce::String heading (const juce::String& title)
    {
        return "\n-- " + title + " --\n";
    }

   #if JUCE_MAC
    juce::String sysctlString (const char* name)
    {
        char buffer[128] = {};
        auto size = sizeof (buffer) - 1;

        if (sysctlbyname (name, buffer, &size, nullptr, 0) == 0)
            return juce::String (buffer);

        return {};
    }

    int sysctlInt (const char* name)
    {
        int value = 0;
        auto size = sizeof (value);

        return sysctlbyname (name, &value, &size, nullptr, 0) == 0 ? value : 0;
    }
   #endif

    juce::String mb (juce::int64 bytes)
    {
        return juce::String (bytes / (1024 * 1024)) + " MB";
    }
} // namespace

juce::String buildDiagnosticsReport (SeparationEngine& engine)
{
    const auto snap = engine.getSnapshot();

    juce::String report;
    report << "SPLITTR DIAGNOSTICS\n";
    report << line ("generated", juce::Time::getCurrentTime().formatted ("%Y-%m-%d %H:%M:%S"));

    // --- build ------------------------------------------------------------
    report << heading ("build");
    report << line ("version", JucePlugin_VersionString);
    report << line ("commit", SPLITTR_GIT_HASH);
    report << line ("built", SPLITTR_BUILD_TIME);
    {
        const auto wrapper = juce::PluginHostType::getPluginLoadedAs();

        report << line ("format",
                        wrapper == juce::AudioProcessor::wrapperType_Standalone
                            ? juce::String ("Standalone")
                        : wrapper == juce::AudioProcessor::wrapperType_Undefined
                            ? juce::String ("unknown")
                            : juce::String (juce::AudioProcessor::getWrapperTypeDescription (wrapper))
                                  + " in " + juce::PluginHostType().getHostDescription());
    }

    // --- machine ----------------------------------------------------------
    report << heading ("machine");
    report << line ("os", juce::SystemStats::getOperatingSystemName());
   #if JUCE_MAC
    report << line ("chip", sysctlString ("machdep.cpu.brand_string"));
    report << line ("cores", juce::String (sysctlInt ("hw.perflevel0.logicalcpu")) + " performance + "
                                 + juce::String (sysctlInt ("hw.perflevel1.logicalcpu")) + " efficiency");
   #endif
    report << line ("memory", juce::String (juce::SystemStats::getMemorySizeInMegabytes() / 1024) + " GB");

    // --- compute ----------------------------------------------------------
    report << heading ("compute");
    report << line ("processing", SeparationEngine::backend() == ComputeBackend::gpu ? "GPU" : "CPU");
    report << line ("metal", DemucsSeparator::gpuStatus());

    // --- models & cache ---------------------------------------------------
    report << heading ("models");

    const auto& models = engine.modelManager();
    report << line ("engine mode", ModelManager::qualityToken (models.quality()).toUpperCase());

    for (const auto& file : models.filesFor (models.quality()))
        report << line (file.existsAsFile() ? "present" : "MISSING",
                        file.getFileName()
                            + (file.existsAsFile() ? " (" + mb (file.getSize()) + ")" : juce::String()));

    {
        juce::int64 cacheBytes = 0;
        auto entries = 0;

        for (const auto& entry : StemCache::enumerate())
        {
            cacheBytes += entry.bytes;
            ++entries;
        }

        report << line ("cache", juce::String (entries) + " entries, " + mb (cacheBytes));
    }

    // --- last run ---------------------------------------------------------
    report << heading ("last run");

    if (snap.sourceFile == juce::File() && snap.stems.empty())
    {
        report << "none this session\n";
    }
    else
    {
        report << line ("source", snap.sourceFile.getFileName());
        report << line ("duration", juce::String (snap.sourceDuration, 1) + " s");
        static const char* phaseNames[] = { "needs model", "downloading", "idle", "decoding",
                                            "separating", "rendering", "ready", "error" };
        report << line ("phase", phaseNames[juce::jlimit (0, 7, (int) snap.phase)]);

        if (snap.inferenceSeconds > 0.0)
            report << line ("inference", juce::String (snap.inferenceSeconds, 1) + " s ("
                                             + juce::String (snap.realtimeFactor, 2) + "x RT) on "
                                             + (snap.usedGpu           ? "GPU"
                                                : snap.gpuRequested    ? "CPU (GPU FELL BACK)"
                                                                       : "CPU"));

        report << line ("bpm", snap.bpm > 0.0
                                   ? juce::String (snap.bpm, 1) + " (conf "
                                         + juce::String (snap.bpmConfidence, 2) + ")"
                                         + (snap.bpmFromDrums ? " via drums fallback" : "")
                                   : "declined (conf " + juce::String (snap.bpmConfidence, 2) + ")");
        report << line ("key", snap.key.isNotEmpty() ? snap.key : juce::String ("declined"));

        if (snap.message.isNotEmpty())
            report << line ("message", snap.message);

        for (const auto& stem : snap.stems)
            report << line ("stem", stem.name + "  " + juce::String (stem.peakDb, 1) + " dB"
                                        + (stem.fx.isFlat() ? juce::String() : juce::String ("  [tuned]"))
                                        + (stem.midiState == EngineSnapshot::MidiState::ready ? "  [midi]"
                                                                                              : ""));
    }

    // --- event log --------------------------------------------------------
    report << heading ("event log");

    const auto events = engine.eventLog();

    if (events.isEmpty())
        report << "quiet so far\n";
    else
        for (const auto& event : events)
            report << event << "\n";

    return report;
}

} // namespace splittr
